// Fleet-command palette. Status colors mean the same thing everywhere (map, HUD, minimap);
// team colors only identify which station (T3 environment) something belongs to.
// This module is the single source of HUD colors: the stylesheet reads them as CSS variables
// generated by hudTokens(), so the HUD follows the active map style.

import { STYLES, type HudMaterials, type StyleId } from "../art/palettes";
import type { UnitState } from "../t3/derive";

export const STATUS: Record<UnitState, number> = {
  alert: 0xff4655,
  question: 0xffd23f,
  working: 0x59e1ff,
  monitoring: 0xb48cff,
  error: 0xff7a3d,
  done: 0x5dff9a,
  // Idle and asleep are told apart by hue, not only lightness: idle a cool grey, asleep a dusk
  // violet (well clear of monitoring's), both clear of muted text and readable on dark panels.
  idle: 0xb3bdcc,
  sleeping: 0x8b85b3,
};

/** Selection on the map: the picked crew member and the box-select, in a colour no status uses. */
export const SELECTION = 0xf4f6f8;

export const HUD = {
  amber: 0xf0a33a,
  cyan: 0x59e1ff,
  text: 0xe6edf3,
  muted: 0x8a96a8,
};

/** The Hermes control center's accent, shared by the map and its panels. */
export const HERMES_COLOR = 0xd6c09c;

/**
 * Context left and host load. A ramp of its own, so a busy CPU or a full context never reads as
 * "needs approval" (red) or "has a question" (yellow). Healthy shares the one "all good" green.
 */
export const GAUGE = {
  ok: STATUS.done,
  high: HUD.amber,
  // Magenta, well clear of the approval red.
  critical: 0xf25cd0,
  unknown: 0x59626c,
};
export type GaugeLevel = Exclude<keyof typeof GAUGE, "unknown">;

/** Context window used (0–1) → gauge level. */
export function contextLevel(used: number): GaugeLevel {
  return used < 0.6 ? "ok" : used < 0.85 ? "high" : "critical";
}

/** Whole-host CPU or RAM utilization (0–1) → gauge level. */
export function loadLevel(fraction: number): GaugeLevel {
  return fraction >= 0.95 ? "critical" : fraction >= 0.85 ? "high" : "ok";
}

/** A map style's HUD frame materials (Night Shift's when the style has none). */
export function hudMaterials(styleId: StyleId): HudMaterials {
  return STYLES[styleId].hud ?? STYLES.nightshift.hud!;
}

/** Every HUD color as a CSS custom property, for one map style. */
export function hudTokens(styleId: StyleId): Record<string, string> {
  const style = STYLES[styleId];
  const m = hudMaterials(styleId);
  const colors: Record<string, number> = {
    space: style.space,
    text: m.text ?? HUD.text,
    muted: m.muted ?? HUD.muted,
    hermes: HERMES_COLOR,
    frame: m.frame,
    ink: m.ink,
    surface: m.surface,
    deep: m.deep,
    slot: m.slot,
    edge: m.edge,
    "edge-strong": m.edgeStrong,
    control: m.control,
    meter: m.meter,
    bright: m.bright,
    ...STATUS,
    "gauge-ok": GAUGE.ok,
    "gauge-high": GAUGE.high,
    "gauge-critical": GAUGE.critical,
    // Host charts plot in the theme's own materials, so a series never reads as a status.
    "chart-cpu": m.bright,
    "chart-ram": m.muted ?? HUD.muted,
    // The map's selection white, for legends that show it.
    selection: SELECTION,
  };
  // On a light HUD the status and gauge hues are deepened until they read as text on its panels;
  // a theme can hand-tune any of them instead.
  if (m.light) {
    for (const name of [...Object.keys(STATUS), "gauge-ok", "gauge-high", "gauge-critical", "hermes"]) {
      colors[name] = deepen(colors[name], m.surface);
    }
  }
  Object.assign(colors, m.tokens);
  // Text on a status fill (pills, alert counts): whichever of the theme's ink or bright reads better.
  for (const state of Object.keys(STATUS)) {
    colors[`on-${state}`] = contrastRatio(m.ink, colors[state]) >= contrastRatio(m.bright, colors[state]) ? m.ink : m.bright;
  }
  const tokens: Record<string, string> = Object.fromEntries(Object.entries(colors).map(([name, color]) => [`--${name}`, css(color)]));
  const chrome = m.chrome ?? { corner: "round", radius: 7, width: 3 };
  tokens["--frame-radius"] = `${chrome.radius}px`;
  tokens["--frame-width"] = `${chrome.width}px`;
  tokens["--corner-shape"] = chrome.corner === "bevel" ? "bevel" : "round";
  return tokens;
}

/** Mix a colour toward black until it has at least 4.5:1 contrast with `surface`. */
export function deepen(color: number, surface: number): number {
  for (let k = 0; k <= 1; k += 0.05) {
    const c = mixColor(color, 0x000000, k);
    if (contrastRatio(c, surface) >= 4.5) return c;
  }
  return 0x000000;
}

function mixColor(a: number, b: number, k: number): number {
  const ch = (x: number, s: number) => (x >> s) & 255;
  const m = (s: number) => Math.round(ch(a, s) * (1 - k) + ch(b, s) * k);
  return (m(16) << 16) | (m(8) << 8) | m(0);
}

/** WCAG contrast ratio between two colours. */
export function contrastRatio(a: number, b: number): number {
  const lum = (c: number) => {
    const [r, g, bl] = [16, 8, 0].map((s) => ((c >> s) & 255) / 255).map((v) => (v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4));
    return 0.2126 * r + 0.7152 * g + 0.0722 * bl;
  };
  const [hi, lo] = [lum(a), lum(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}

/** Dark plating for map structures drawn in HUD materials (stays dark on light-HUD themes). */
export function platingMaterials(styleId: StyleId): HudMaterials {
  const m = hudMaterials(styleId);
  return m.plating ? { ...m, ...m.plating } : m;
}

/** Point the stylesheet at a map style's HUD colors. */
export function applyHudTheme(styleId: StyleId): void {
  const root = document.documentElement;
  for (const [name, value] of Object.entries(hudTokens(styleId))) root.style.setProperty(name, value);
  root.dataset.art = styleId;
  root.dataset.hud = hudMaterials(styleId).light ? "light" : "dark";
  document.querySelector('meta[name="theme-color"]')?.setAttribute("content", css(STYLES[styleId].space));
}

/**
 * Distinct station colors, chosen to stay clear of the status and gauge colors above (no amber,
 * orange, red, magenta or violet; see theme.test.ts for the separation each keeps).
 */
// Olive, not bronze, in the fifth slot: bronze read as Kestrel's own chrome.
export const TEAM_COLORS = [0x3ec7b3, 0x5b7cff, 0xa8d65a, 0x2fa36b, 0x8a8f3c, 0x1f9fd6];

/**
 * A station or bot colour as the HUD should show it: as is on dark HUDs, deepened to readable
 * text on light ones (lime on cream is 1.5:1).
 */
export function hudAccent(color: number, styleId: StyleId): number {
  const m = hudMaterials(styleId);
  return m.light ? deepen(color, m.surface) : color;
}

/** Text and line colours for labels drawn on the map (over space or dark plating), per style. */
export function mapInk(styleId: StyleId): { text: number; muted: number; line: number } {
  const ink = STYLES[styleId].mapInk;
  return { text: ink?.text ?? HUD.text, muted: ink?.muted ?? HUD.muted, line: ink?.line ?? platingMaterials(styleId).edgeStrong };
}

export function teamColor(index: number): number {
  return TEAM_COLORS[index % TEAM_COLORS.length];
}

/**
 * Visor glass by provider: low-saturation tints that never read as a status (Claude's orange and
 * Codex's teal used to sit beside failed and working). Providers are told apart by helmet shape.
 */
export const PROVIDER_VISOR: Record<string, number> = {
  claudeAgent: 0xc8b48c, // gold leaf
  codex: 0xa9c4d4, // pale blue
  cursor: 0x9a94b0, // smoke violet
  grok: 0x56606c, // dark mirror
  opencode: 0xb39c86, // copper
};
/** Visor glass for providers not listed above. */
export const DEFAULT_VISOR = 0xb4bfcc;

// ---- Crew classes ----------------------------------------------------------------------

/** How big and well-equipped a crew member looks, from its model. */
export type Tier = "light" | "standard" | "heavy" | "reviewer";

/**
 * Model slug → tier. First match wins; anything unmatched is "standard". The Codex names are a
 * best guess from their naming (Sol > Astra/Terra > Luna); adjust here if that's wrong.
 */
const TIER_RULES: Array<[RegExp, Tier]> = [
  [/review/i, "reviewer"],
  [/haiku|luna|mini|nano|flash|lite/i, "light"],
  [/opus|fable|(^|[-.])sol($|[-.])|ultra|max|pro/i, "heavy"],
];

export function modelTier(model: string): Tier {
  return TIER_RULES.find(([re]) => re.test(model))?.[1] ?? "standard";
}

export const TIER_LABEL: Record<Tier, string> = {
  light: "Scout",
  standard: "Specialist",
  heavy: "Heavy",
  reviewer: "Inspector",
};

/** Suit silhouette by provider: Claude crew are rounded, Codex crew are angular. */
export type Silhouette = "round" | "angular";

export function providerSilhouette(instanceId: string): Silhouette {
  return instanceId === "codex" || instanceId === "cursor" || instanceId === "opencode" ? "angular" : "round";
}

export function css(color: number): string {
  return `#${color.toString(16).padStart(6, "0")}`;
}
